import type { Metadata } from 'next';

export const SITE_NAME = 'TaskTrack';
export const SITE_DESCRIPTION =
  'TaskTrack helps students organize schoolwork, track deadlines, and see what is done.';

/** The share image generated by app/opengraph-image.tsx. */
const SHARE_IMAGE = {
  url: '/opengraph-image',
  width: 1200,
  height: 630,
  alt: 'TaskTrack: a simple task manager for students',
};

/** Absolute site URL used for canonical links, Open Graph URLs, robots.txt, and the sitemap. */
export function getSiteUrl(): URL {
  if (process.env.NEXT_PUBLIC_SITE_URL) return new URL(process.env.NEXT_PUBLIC_SITE_URL);
  if (process.env.VERCEL_PROJECT_PRODUCTION_URL) {
    return new URL(`https://${process.env.VERCEL_PROJECT_PRODUCTION_URL}`);
  }
  return new URL('http://localhost:3000');
}

interface PageMetadataOptions {
  title: string;
  description: string;
  /** Route path, such as "/tasks". Resolved against metadataBase in the root layout. */
  path: string;
  /** Skip the "| TaskTrack" title suffix, for pages whose title already names the app. */
  absoluteTitle?: boolean;
}

/**
 * Builds metadata for a page so every route sets the same fields: title,
 * description, canonical URL, Open Graph, and Twitter card. Next.js replaces
 * rather than merges a parent's openGraph object, so each page has to supply
 * the full set itself, including the share image, which is what this helper is for.
 */
export function pageMetadata({
  title,
  description,
  path,
  absoluteTitle = false,
}: PageMetadataOptions): Metadata {
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title,
      description,
      url: path,
      siteName: SITE_NAME,
      type: 'website',
      locale: 'en_US',
      images: [SHARE_IMAGE],
    },
    twitter: {
      card: 'summary_large_image',
      title,
      description,
      images: [SHARE_IMAGE.url],
    },
  };
}
